quests[41702] = { id = 41702, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Written in Stone", description = "<You bundle the notes and store them away in your pack.\n\nAccording to his final journal entry, Kel'danath used something called a \"spellstone\" in his experiments.\n\nThe spellstone, if not the arcanist himself, must be nearby.>", progress = "<This withered seems entranced by the spellstone. He is completely pacified.>", completion = "<A small tag hanging from his sleeve reads \"16 - Theryn.\">", objectives = "Retrieve the Spellstone of Kel'danath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41703] = { id = 41703, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "DANGER: Ormagrogg" }
quests[41704] = { id = 41704, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Subject 16", description = "<It seems Theryn is still under the arcanist's spell. In the absence of Kel'danath himself, a live subject could be useful in helping Thalyssra unravel his research.>", completion = "So, Kel'danath turned in the end...\n\nHe deserved better. Thank you for giving him peace.", objectives = "Deliver Theryn to Thalyssra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41705] = { id = 41705, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Thunder Totem" }
