quests[41707] = { id = 41707, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wormtalon Wreckage", description = "As if Shaladrassil's encroaching roots were not enough to deal with, now the Wormtalon harpies have come to take advantage of our plight. \n\nKill them, {race}. They deserve nothing less for feeding on our misery.", completion = "Such violence should not be necessary. Thank you, regardless.", objectives = "Slay 15 Wormtalon Harpies in Shadowfen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41708] = { id = 41708, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Side of the Moon", description = "Xavius led Ysera past here, but their destination is unclear. This twisted wickedness smothers my mind!\n\nThese refugees tell of an ancient Moonwell hidden in the ruins of their home. If it somehow resisted this corruption...\n\nI will beg of Elune a vision to give me direction. With her light, I may find my husband yet.", completion = "He is still alive, but the rest remains to be seen.", objectives = "Protect Tyrande while she holds her vigil at the Ancient Moonwell.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41709] = { id = 41709, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking Down the Big Guns", description = "You did well against that sea witch, but not well enough.\n\nHer power far surpasses any creature that I have ever fought. To defeat her, we will need something formidable. Something that she will not expect...\n\n<Toryl grins wryly.>\n\nSomething of their own design... \n\nSalvage as many parts from their harpoon launchers as you can carry and meet me back in Jandvik.", progress = "The Tidemistress is a dangerous foe. We must be just as cunning to defeat her.", completion = "You have all the parts that you will need... two in some cases.", objectives = "Collect 50 Harpoon Parts from Sashj'tar Harpooners in Azuregale Bay.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41710] = { id = 41710, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legion 110 A" }
