quests[41833] = { id = 41833, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grmlrml's Last Ride" }
quests[41834] = { id = 41834, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Masks We Wear", description = "Many nightborne had pinned their hopes on Thalyssra deposing the Grand Magistrix. Since she disappeared, dissenting voices have grown silent.\n\nWe must spread the word, discreetly, among the populace. Ly'leth Lunastre will be a perfect ally in this. She is a socialite with many connections, and she is no friend of the Legion.\n\nLy'leth hosts a masquerade party at her estate where rumors are traded like coin - and brandished like daggers.\n\nLet us invite ourselves in.", progress = "Pleased to make your acquaintance.", completion = "That mask suits you.\n\nIn Suramar, it can be quite advantageous to be someone else for a time...", objectives = "Speak with 8 Masqued Revelers while in costume, then speak with Ly'leth Lunastre.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41835] = { id = 41835, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deworming" }
quests[41836] = { id = 41836, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Bodash the Hoarder" }
quests[41837] = { id = 41837, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rockaway Bully" }
quests[41838] = { id = 41838, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Slumber" }
quests[41839] = { id = 41839, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Taken", description = "When Mayla's father was taken, so were the corpses of several of our greatest chieftains.\n\nThe Grey One, even now, is priming Mayla's father to be a vessel for his evil agenda.\n\nBut the others have already been taken by the necrodark, their corpses now vessels for malevolent drogbar spirits.\n\nI will be honest, I do not think my skills could defeat these monstrosities.\n\nWe need your help!", objectives = "Defeat the Taken Chieftains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41840] = { id = 41840, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ice and Shadow", description = "We took down one of the Necrodark. Ebonhorn found that it held a shard of ice infused with shadow essence.\n\nPerhaps the villains are using these shards as a kind of talisman. I suggest you deprive them of their trinkets.\n\nI know little of such magics, but it seemed that Ebonhorn had a use for them in mind.", progress = "Did you find more of the shards?", completion = "Perfect timing, {name}. These shards will prove very useful in what I'm about to do.", objectives = "Collect 20 Shadowice Shards.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41841] = { id = 41841, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Final Ward", description = "The Necrodark are readying their ritual to give physical form to the Darkness. They've sealed themselves inside and barred our way.\n\nThe shards you brought me should provide the means to bring down the barrier. Once it is done, we have to act quickly. We must restore the final ward before the Darkness can manifest.\n\nDo not hesitate. The fate of Highmountain itself hangs in the balance.", progress = "This is the hardest challenge I have ever had to face.", completion = "We failed! The ward is shattered.\n\nI sense the Darkness rising...", objectives = "Restore the Summit Ward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41842] = { id = 41842, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bottom of the Food Chain" }
quests[41843] = { id = 41843, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bad Luck, Puck" }
quests[41844] = { id = 41844, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Sekhan" }
quests[41848] = { id = 41848, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legion Invaders" }
quests[41849] = { id = 41849, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Iron Fist", description = "It's time to send a rescue operation to the Gates of Valor, {name}.\n\nI will prepare our troops and send them at once. We will need a sizable army to take on the massive Legion force in Stormheim.\n\nGrandmaster, go ahead whenever you are ready. I will send our forces to meet you in the field.", completion = "They made you Grandmaster, eh? Well, I was busy anyway!\n\nAnyway, I managed to escape from those fel-drinking dirt-kickers across the road, but our own are still in trouble.\n\nThose Legion worms are goin' ta sacrifice the prisoners for their souls.\n\nWe've got ta help them!", objectives = "Speak to Angus Ironfist at Tideskorn Warcamp in Stormheim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41850] = { id = 41850, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Master of Swords", description = "I got bad news fer ya - we don't have time to wait for reinforcements. They're sacrificin' prisoners now! Every minute we wait here jabberin' is another life on the line!\n\nFirst things first, my friend Sylara is being held captive in the camp just across the road.\n\nWe need ta free her - she'll be a valuable ally.\n\nWe've got ta move move move!", progress = "Something need punching?", completion = "Good, ye did it. Sylara is worth ten well-trained monks.", objectives = "Collect Dravax's Key from Dravax, then free Sylara Steelsong.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41851] = { id = 41851, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quelling the Tide", description = "<Sylara looks at you with determined eyes.>\n\nOur friends are in danger. We will save them. Kill any Legion in the way.", progress = "<Sylara nods at you.>", completion = "<Sylara bows deeply.>\n\nWell fought.", objectives = "Kill 16 Legion defenders at the Gate of Valor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41852] = { id = 41852, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Monk Left Behind", description = "Most of the prisoners are being held in the main camp at the Gates of Valor.\n\nOur people have been beaten and tortured, and worse still awaits for them if we don't save them.\n\nFind the cages within the main camp and free as many monks as you can find.\n\nI'll be right beside you, knocking heads and taking names!", progress = "Did we free them all?", completion = "Good work, Grandmaster!\n\nThat should be all of them.", objectives = "Free 6 Tortured Prisoners.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41853] = { id = 41853, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zero to Hiro", description = "I have a favor to ask of you, {name}. My good friend Hiro is still somewhere inside the main camp.\n\nOnly problem is, the Gates of Valor are swarming with the biggest, baddest, nastiest Legion creatures I've ever seen. If we walk in there, we'll just get slaughtered.\n\nBut I've seen these vrykul chugging some kind of special brew called Storm Brew. It's some kind of combat tonic that makes them bigger and stronger.\n\nLet's steal some of that drink, then storm in to save Hiro!", completion = "Ahhh, tanks be to ya for freein' me. I thot I was demon-food for sure.", objectives = "Steal a Storm Brew, then save Hiro.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41854] = { id = 41854, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brick By Brick", description = "Da monks be free, and we put a thorn in dat eredar lady's side.\n\nI'm back wit my friends, and lookin' forward to sleepin' in a bed tonight.\n\nLet's go back ta da Wanderin' Isle. I've never been so excited ta see a turtle in my life.", completion = "This is fantastic news, {name}!\n\nNot only have you disrupted the Legion's plans, but you've saved the lives of numerous people.\n\nIn addition, you rescued three of the greatest monks we've trained in recent history.\n\nThe order is indebted to you once again.", objectives = "Return to Iron-Body Ponshu on the Wandering Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41855] = { id = 41855, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stand Up to Bullies" }
