quests[41862] = { id = 41862, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Only Pets Can Prevent Forest Fires" }
quests[41863] = { id = 41863, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vengeance Will Be Ours", description = "Caria lies in the very heart of Legion territory - they'll see our forces immediately if we try to launch an all-out attack.\n\nFailure is not an option.\n\nHowever, if you go alone you might be able to slip by unnoticed long enough to avoid the brunt of the Legion army.\n\nRemember, {name} - this is not a rescue mission. The power of the Aldrachi Warblades could tip the scales of this war in our favor; Allari and her men are expendable if need be.", completion = "What of the others? Did they...?\n\nI see. They gave their lives for a worthy cause - the Warblades will change the tide of this war, mark my words.", objectives = "Take the Aldrachi Warblades from Caria Felsoul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41864] = { id = 41864, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neltharion's Lair: Crystalline Crusher" }
