quests[41873] = { id = 41873, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mead Master", description = "The vyrkul meadery overlooks the coast in northern Stormheim. Meet me there when you are ready, {name}.", objectives = "Speak to Apprentice Meldir in Stormheim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41874] = { id = 41874, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talked to Tyrande to Start Events" }
quests[41875] = { id = 41875, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Found First Clue" }
quests[41876] = { id = 41876, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Umbraxis Tracker" }
quests[41877] = { id = 41877, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lady Lunastre", description = "Our friend Ly'leth contacted me. She requested that you meet her atop the Grand Promenade as it overlooks the city.\n\nHave your disguise ready just in case, {name}.", progress = "Hm?", completion = "I hope you have prepared yourself to enter the City. It is time.", objectives = "Seek out Ly'leth at the Grand Promenade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41878] = { id = 41878, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gondolier", description = "I need your help.\n\nThe wine you so graciously distributed to the needy was the last of my reserves. Without more, these people here will risk succumbing to their thirst, and eventually becoming withered.\n\nI am dedicated to preventing this for as long as possible.\n\nThere is a woman by the name of Deline who owns and operates a small delivery service out of her gondola.\n\nFind her, identify yourself as my messenger, and offer your aid in acquiring the next shipment.", progress = "Unless you want a ride, you should keep moving.", completion = "Let's get started, shall we?", objectives = "Make contact with the Gondolier.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41879] = { id = 41879, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "TBD" }
quests[41880] = { id = 41880, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den of Shadows", description = "Placeholder: Thalyssra sends you to find Arluin Shadowblade, a deft assassin once in her employ/social circle. (whichever fits) Indicate that he would be an invaluable asset to making progress in the City with covert operations.", objectives = "Make contact with Arluin Shadowblade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41881] = { id = 41881, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fight Night: Heliosus" }
quests[41882] = { id = 41882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whispers of the Darkness", description = "Before our arrival, many of our own came to neutralize the threat here. They did not know what they were walking into.\n\nOur people are now suffering from the whispers. The Old Gods seek to corrupt them and turn them against their own.\n\nWake them from their stupor. Free them from the whispers any way you can.", completion = "Well done, {name}. If left unchecked, the whispers can turn even the best of friends against one another.", objectives = "Free 6 Highmountain Protectors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41884] = { id = 41884, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Tales", description = "Spiritwalker Ebonhorn is stable... for now.\n\nHe once told me of the wards he maintains against the Old Gods. He placed them at key locations around this mountain, but kept them hidden from mortal eyes--even my own.\n\nIncapacitated like this, his wards cannot hold back the evil ones. No doubt this is the reason for their attack.\n\nTo find the wards, we must enter the echoes of Ebonhorn's past and commune with the spirits we find there.\n\nMeet me in Riverbend, {name}. It is there our search begins.", completion = "The spirits hold many truths, {name}.\n\nWalking in their footsteps may reveal the locations of Ebonhorn's wards.", objectives = "Meet Spiritwalker Graysky in Riverbend.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41885] = { id = 41885, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Naralex Kneel Seen" }
quests[41886] = { id = 41886, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fight Night: Rats!" }
quests[41888] = { id = 41888, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Allegiance of Flame", description = "My rivals lay dead and there are none within the Firelands who dare oppose my rule!\n\nAs promised, I will unite with the other Elemental Lords in the defense of Azeroth. The armies of the Firelands will scorch the battlefield with the corpses of our enemies!\n\nGo now, mortal. Tell your Earthen Ring that the Firelord himself stands with you!", progress = "What news do you bring from the Firelands?", completion = "I did not think that I would live to see the day when the four great Elemental Lords would unite with the mortal races of Azeroth.\n\nYou have done what no other Farseer has done in the history of the Earthen Ring.\n\nThis is truly a day that will be remembered for generations!", objectives = "Speak with Farseer Nobundo in The Heart of Azeroth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41889] = { id = 41889, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dazed of the Past", description = "Let's begin crafting this mount armor, shall we?", progress = "I'm quite anxious to see how it turns out.", completion = "Is there anything we can't do? I'm starting to think not!\n\nI'll make sure this barding gets to Mei. You hold on to the pattern and maybe you can make some profit with it.", objectives = "Construct a Stonehide Leather Barding.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41890] = { id = 41890, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Side of the Moon", description = "Xavius has been this way, but his destination is unclear. The Nightmare smothers my mind!\n\nThese refugees tell of an ancient Moonwell hidden in the ruins ahead.\n\nIf it is uncorrupted, it will give me the focus I need. By Elune's light, we will find my husband yet.\n\nMeet me at the Moonwell at once, {class}.", completion = "He is still alive, but the rest remains to be seen. For your sake, let us pray that he is unharmed.", objectives = "Protect Tyrande while she holds her vigil at the Ancient Moonwell.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41891] = { id = 41891, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tainted Growth", description = "The blood red petals of the Nightmare Flower seethe with chaotic energy. The plant twitches every now and then, releasing puffs of pollen into the air. \n\nThe nearby satyrs and keepers can be seen harvesting similar plants for little crimson seeds.\n\nThese seeds must be destroyed.", objectives = "Collect 5 Corrupted Seedlings and return them to Tyrande.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41893] = { id = 41893, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Given to Corruption", description = "A final favor for an old friend, perhaps? My age-old companion, Varethos, has fallen to the nightmare's torment. We once worked in unison to protect this land. His close ties to the land brought him low in this dark hour.\n\nAs with all who suffer this fate, there is no restoring him.\n\nPlease, {name}, bring him peace.", progress = "Is it done, then?", completion = "My sight fades, but I am glad that he rests.", objectives = "Slay Keeper Varethos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41895] = { id = 41895, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Master of Pets" }
quests[41896] = { id = 41896, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation Murloc Freedom" }
quests[41897] = { id = 41897, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Master's Plan", description = "The purpose of the Twilight's Hammer has always been the same. They seek to bring about the end of the world. Their schemes may change, but their wicked purpose remains constant.\n\nDefeating the Twilight's Hammer is not simply a matter of defeating them in battle. If we are to be successful, we will need to uncover their scheme and put an end to whatever terrible plans they have created.\n\nLet us start by searching the encampment for clues as to their true purpose here.", progress = "What vile scheme have the Twilight's Hammer plotted against the world this time?", completion = "If The Master is not stopped, the Twilight's Hammer will have all the power they need to conquer Deepholm and enslave the elements!\n\nWe must not allow that to happen.", objectives = "Collect the excerpts from The Master's Journal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41898] = { id = 41898, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unleashing the Elements", description = "According to The Master's journal, the Twilight's Hammer has discovered a method of harnessing the void to subjugate even the most powerful of elementals.\n\nThe journal specifically mentioned the children of Therazane as test subjects. Whether The Master was speaking literally or figuratively in this regard, I do not know. Regardless, we need to free these elementals and stop these dark rituals from continuing.\n\nIt appears that our journey here is going to take us deeper into the depths of darkness...", progress = "Dark rituals such as these must not be allowed to continue.", completion = "The servants of Therazane are free and the dark rituals of subjugation have been halted... for now.", objectives = "Release the Servants of Therazane from Twilight Depths.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41899] = { id = 41899, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Held Captive!", description = "There are prisoners here, Farseer {name}, that are enslaved by the Twilight's Hammer.\n\nThe cultists work them to death in the depths of the mine.\n\nI cannot abide such cruel mistreatment! Let us clear a path through the mine and rescue any Twilight's Hammer prisoners we find, so that they may return to their homes and families.\n\nThe Twilight's Hammer will pay for their crimes!", progress = "Have the slaves been rescued?", completion = "The captives have been set free, but there is still much more to be done if we are to dismantle the Twilight's Hammer cult...", objectives = "Rescue 10 Twilight Slaves from the Twilight Depths.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41900] = { id = 41900, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Promise of Earth", description = "Deepholm thanks you, shaman.\n\nThe Twilight's Hammer has always sought dominion over my kingdom, but this latest threat was far greater than their previous efforts.\n\nFor your service to the elements of earth, I will pledge my armies to the Earthen Ring in the defense of Azeroth.\n\nI have no love for the mortal races, but this world is not the Burning Legion's to destroy.\n\nTell your Earthen Ring that Therazane the Stonemother stands with them!", completion = "It is good to see you safely back, Farseer. With Therazane's allegiance, we now have three of the Elemental Lords united to our cause.\n\nHowever, one still remains...", objectives = "Speak with Advisor Sevel in the Heart of Azeroth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41901] = { id = 41901, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oath of the Windlord", description = "You have my thanks, mortal for bringing about my rebirth. However, thanks alone would not be honorable.\n\nI know that the Earthen Ring seeks to save Azeroth from the Burning Legion.\n\nI will pledge my sword, and the armies of Skywall to the aid of Azeroth.\n\nWhen the time for battle arrives, and the Earthen Ring stands upon the battlefield against the Burning Legion, the Windlord shall stand with you.", completion = "The Windlord has pledged to aid The Earthen Ring in the war against the Burning Legion?\n\nThis is fortuitous news indeed!\n\nStill, there is little time for celebration, much remains to be accomplished.", objectives = "Speak with Advisor Sevel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41903] = { id = 41903, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gathering the Pieces", description = "Grand Master, the Mission Table is now at your disposal.\n\nThere are several strategic areas where we can focus our Order's efforts.\n\nFirst, we should check on the status of the other monk temples. It seems the Legion has a special focus on destroying us.\n\nSecond, we need to scour the seas near the Broken Shore. There are still many missing from the battle.\n\nFinally, there is the continued appearance of demonic forces at numerous points across the Broken Isles. They must be kept at bay.", objectives = "Interact with the Mission Table and complete five Order Hall missions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41905] = { id = 41905, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report from Tian Monastery", description = "We have heard from all our temples on Pandaria, except for one.\n\nWe dispatched a message by bird to Tian Monastery, but no answer has yet arrived. This silence is quite unusual.\n\nGrandmaster, I recommend that we send our champion, Chen Stormstout, to scout the situation at once.", progress = "What have you discovered?", completion = "Your champion moved swiftly, {name}! This report clearly indicates that Tian Monastery is under attack!", objectives = "Use the Scouting Map and complete the mission, \"Investigate Tian Monastery.\"", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41907] = { id = 41907, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Appropriations", description = "I have come to lend my help to the Order of the Broken Temple.\n\nMy job is to create a solid base of operations around here. Right now, we have wounded to tend and bellies to feed. After this, we can worry about building our defenses.\n\nLao Shu is in charge of our supply inventory. Go and speak with him now in the inn.", completion = "Ah, yes yes yes! High Elder Cloudfall was right to send you to me.", objectives = "Speak to Lao Shu in The Laughing Crane inn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41909] = { id = 41909, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking the Tideskorn", description = "We have sent scouts to search for our kidnapped allies, and our efforts may have finally paid off.\n\nThey've tracked them to the vrykul homeland of Stormheim, but the unfamiliar territory has slowed our progress and we're in danger of losing the trail.\n\nI suggest that we send our champions immediately to assist with the tracking effort.", progress = "Did we gather enough information about the Legion forces at the Gates of Valor?", completion = "Excellent. It will be extremely dangerous to infiltrate the Gates, but with this information, we will know exactly the enemy's location and numbers.", objectives = "Use the Scouting Map and complete the \"Tracking the Tideskorn\" missions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41910] = { id = 41910, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freya's Spring", description = "First, we need water from Freya's Spring.\n\nOnce a year, on the first day of solstice, the sun hits the white-capped summit of the highest peak in Highmountain. The melting snow runs through a ravine and collects in a crystalline pool.\n\nSome say these waters grant eternal youth. Silly stories if you ask me, but we will need this rare, purified water for our brew.\n\nI suggest sending our champions to collect us a sample, for your skills will be needed elsewhere.", completion = "This water is filtered from only the freshest fallen snow every winter, and is a vital ingredient to our brew!", objectives = "Use the Scouting Map and complete five \"Freya's Spring\" missions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41911] = { id = 41911, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amaranthine Hops", description = "The hops for our brew must be a very specific, and they will also be hard to acquire.\n\nAmaranthine Hops only grow in the realm known as the Emerald Dream, meaning we can only acquire this ingredient from a druid.\n\nThere is one such supplier from whom I receive this item, but she may ask for something in exchange.", progress = "Did you find Fleuris?", completion = "Mmmm, just smell those hops! This will be a good batch, I just know it.", objectives = "Speak to Fleuris Asterleaf in Val'sharah and trade 20 Stonehide Leather for 1 bag of Amaranthine Hops.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41914] = { id = 41914, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clear the Catacombs" }
quests[41915] = { id = 41915, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Master's Legacy", description = "You work for a murderer and a thief.\n\nThat design he wants? It is called the magistrix cut, and it was perfected by my husband. He was killed by Lespin for his secret.\n\nI had him entombed in a small cave north of the city, for we could not make the trip to Tel'anor. Buried with him is a tome that contains the secrets of the design.\n\nRetrieve the design and keep it out of his hands!", progress = "Where is the master?", completion = "Well well, looks like that old fool finally met his match?\n\nIt looks like the Promenade is in need of a new jeweler, and I think I have learned all I could from my former master.\n\nHere is something for your efforts.", objectives = "Investigate the Gemcutter's Tomb.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41916] = { id = 41916, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Better Future", description = "We must move quickly, {name}. I must save as many of my people as I can before the attack begins.\n\nWord has gotten out in the city that there is a safe haven with us and some no longer fear exile.\n\nVenture into the Grand Promenade, champion. Find those willing to join us and let them know it is time they made their escape.", progress = "Each shal'dorei rescued is both a potential enemy vanquished and a new hope for our people.", completion = "Our strength grows and our enemies wane. We will win this fight, {name}!", objectives = "Rescue 8 Shal'dorei Insurgents in the Grand Promenade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41917] = { id = 41917, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Bear Cub" }
quests[41918] = { id = 41918, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dreamer Returns", description = "Arch Druid Greathoof will be expecting word on the success of our mission, but I'm afraid I must ask you to return alone.\n\nI can't rest knowing that Xavius has Lord Ursoc in his clutches. Just the thought of it makes me shake with rage! I'll find where he has been taken if I have to search every corner of Azeroth!\n\nOur paths will cross again, {name}. Be sure of it.", completion = "So, Xavius is behind this. A thousand deaths isn't enough of a punishment for that defiler!\n\nBut, you have returned with the claws, that is not an accomplishment that even I could have performed.\n\nYou are truly the hero we need to face the Legion.", objectives = "Return to Arch Druid Greathoof in the Dreamgrove. You may use Dreamwalk to travel via the Emerald Dreamway.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41919] = { id = 41919, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shadows Reveal", description = "The Fangs of the Devourer are wielded by Akaari Shadowgore, one of Kil'Jaeden's personal assassins. Every attempt on her life ends the same... she's gone before we even arrive.\n\n<Valeera scrawls a few lines on a piece of paper, then hands it to you.>\n\nBut not this time. We've been working with these contacts to find Akaari so we can finally take the Fangs for our own purposes.\n\nGo to each contact and tell them \"The shadows reveal.\" See what they know.", progress = "Hmm?", completion = "<Valeera glances in your direction.>\n\nAny luck?", objectives = "Speak to your contacts in Dalaran to acquire intel on Akaari Shadowgore's whereabouts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41920] = { id = 41920, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Matter of Finesse", description = "A rune of portals?! Who does Val'zuun think he is?\n\n<Valeera takes a deep breath.>\n\nIt's worth the price, but those runes aren't exactly easy to come by. Unless...\n\nArchmage Celindra, the Kirin Tor's portal master, has a study in the center of town. We rogues aren't particularly welcome there, nor would she simply hand a rune over even if we were...\n\n<Valeera smirks.>\n\nBut who said anything about asking?", progress = "They say the Fangs of the Devourer have no equal. If that's true, they're worth any price.", completion = "Val'zuun actually kept his end of the bargain... I'm impressed.", objectives = "Borrow a Rune of Portals from Archmage Celindra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41921] = { id = 41921, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Closing In", description = "The Legerdemain Lounge isn't far from here. We have agents nearby who can secure the area.\n\nCome prepared for a fight. Akaari won't go down easily.", progress = "I can't believe it...", completion = "It was a ruse?!", objectives = "Confront Akaari Shadowgore in the Legerdemain Lounge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41922] = { id = 41922, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traitor!", description = "That lying demon SCUM! I should have known.\n\nLet's show Val'zuun what happens to people who dare cross the Uncrowned.", completion = "He's lying again, I know it... but he might be our only option.", objectives = "Join Valeera Sanguinar in the Underbelly Descent.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41924] = { id = 41924, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fangs of the Devourer", description = "If you spare me I can use the rune of portals you provided to open a gateway to Akaari's citadel in the Twisting Nether.\n\nOf course, killing the Legion's master assassin in her own domain will be no simple feat, but surely the Fangs of the Devourer are worth the risk, no?\n\n<Val'zuun smiles.>\n\nI will guide you through the citadel once you arrive, but you will have to defeat Akaari on your own.", progress = "Any luck?", completion = "I knew you'd succeed, {name}. I'm glad you're on our side.", objectives = "Obtain the Fangs of the Devourer from Akaari Shadowgore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41925] = { id = 41925, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Razing Hel" }
quests[41926] = { id = 41926, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Returning Champion" }
quests[41927] = { id = 41927, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruining the Runewood" }
quests[41929] = { id = 41929, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tutorial Lockbox Looted" }
quests[41930] = { id = 41930, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valor Calls" }
quests[41931] = { id = 41931, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mana Tap" }
quests[41932] = { id = 41932, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legion Portal" }
quests[41933] = { id = 41933, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legion Portal" }
quests[41934] = { id = 41934, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Brand of Damnation", description = "I require a symbol of my dominion as Firelord. A weapon that will strike fear into the hearts of all who dare to oppose my rule!\n\nDeep within the den of the Cinderweb, there is an ancient spear born from within the heart of the Firelands. Emberscar is a living weapon whose wicked power is beyond mortal comprehension.\n\nProve your strength and claim Emberscar in my name! If you survive, perhaps I will aid the feeble races of humanity against the Burning Legion.", progress = "The Brand of Damnation will be mine!", completion = "I see that you have successfully awakened Emberscar, and that it has been well-fed.\n\nPerhaps you are stronger than I first thought...", objectives = "Retrieve Emberscar, Brand of Damnation.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41935] = { id = 41935, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beasts of Burden" }
